import {
  showErrorMessage,
  showSuccessMessage,
} from '/static/js/common/notification.prod.js';
export function debounce(e, t = 500) {
  let a;
  return function (...o) {
    (clearTimeout(a),
      (a = setTimeout(() => {
        e.apply(this, o);
      }, t)));
  };
}
export function checkEmail(e) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
}
export function validatePassword(e) {
  return e.length < 8
    ? 'The password is too short.'
    : /\d/.test(e)
      ? /[a-zA-Z]/.test(e)
        ? /[^a-zA-Z0-9\s]/.test(e)
          ? null
          : 'Enter a special character - !@#$%^&*(){}[],./'
        : 'Enter an alphabet letter A-Z.'
      : 'Enter a number 0-9.';
}
export function parseDuration(e) {
  const t = e.match(/^P(?:(\d+)D)?T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?$/);
  if (!t) return 0;
  return (
    86400 * Number(t[1] || 0) +
    3600 * Number(t[2] || 0) +
    60 * Number(t[3] || 0) +
    Number(t[4] || 0)
  );
}
const COOLDOWN_KEY = 'login_cooldown_until';
let Timeout = null;
export function startCooldown(e) {
  const t = Date.now() + 1e3 * e;
  (localStorage.setItem(COOLDOWN_KEY, t),
    clearTimeout(Timeout),
    updateCooldown());
}
export function updateCooldown() {
  clearTimeout(Timeout);
  const e = $('#formButton'),
    t = Number(localStorage.getItem(COOLDOWN_KEY));
  if (!t) return void e.prop('disabled', !1);
  const a = Math.ceil((t - Date.now()) / 1e3);
  if (a <= 0)
    return (
      localStorage.removeItem(COOLDOWN_KEY),
      e.prop('disabled', !1),
      showSuccessMessage('Lockdown Lifted', 'Redirecting you'),
      void window.location.reload()
    );
  const o = Math.floor(a / 60),
    n = a % 60;
  (e.prop('disabled', !0),
    showErrorMessage(
      'Lockdown Initiated',
      `Try again after ${o} minute(s) and ${n} second(s)`
    ),
    (Timeout =
      a < 60
        ? setTimeout(updateCooldown, 1e3 * a)
        : setTimeout(updateCooldown, 6e4)));
}
function urlBase64ToUint8Array(e) {
  const t = (e + '='.repeat((4 - (e.length % 4)) % 4))
      .replace(/-/g, '+')
      .replace(/_/g, '/'),
    a = window.atob(t);
  return Uint8Array.from([...a].map((e) => e.charCodeAt(0)));
}
export async function enableNotifications() {
  const e = $('#vapid_public_key').val(),
    t = await Notification.requestPermission();
  let a = $('[name="csrftoken"]')[0].content;
  if ('granted' !== t)
    return void showErrorMessage(
      gettext('Notifications Denied'),
      gettext('Kindly allow Notifications.')
    );
  showSuccessMessage(
    gettext('Notifications Accepted!'),
    gettext('Notifications have been allowed.')
  );
  const o = await navigator.serviceWorker.ready,
    n = await o.pushManager.subscribe({
      userVisibleOnly: !0,
      applicationServerKey: urlBase64ToUint8Array(e),
    });
  $.ajax({
    type: 'POST',
    url: '?action=activate_notifications',
    headers: { 'X-CSRFToken': a },
    data: JSON.stringify(n.toJSON()),
    success: function (e) {
      e.status
        ? showSuccessMessage(
            gettext('Notifications Registered'),
            gettext('You can now receive notifications.')
          )
        : showErrorMessage(
            gettext('Notifications Error'),
            gettext('Kindly Try again')
          );
    },
  });
}
export async function unsubscribeNotifications() {
  const e = await navigator.serviceWorker.ready;
  let t = $('[name="csrftoken"]')[0].content;
  const a = await e.pushManager.getSubscription();
  a &&
    (await a.unsubscribe(),
    $.ajax({
      type: 'POST',
      url: '?action=silence_notifications',
      headers: { 'X-CSRFToken': t },
      data: JSON.stringify({ endpoint: a.endpoint }),
    }));
}
export function handleHttpError(e) {
  switch (e) {
    case 401:
      window.location.href = '/login/';
      break;
    case 403:
      showErrorMessage(
        gettext('Not Authenticated'),
        gettext('You do not have permission to do that.')
      );
      break;
    case 404:
      showErrorMessage(
        gettext('Not Found'),
        gettext('The requested resource was not found.')
      );
      break;
    case 500:
      showErrorMessage(
        gettext('An Error Occurred'),
        gettext('Server error. Please try again later.')
      );
  }
}
export function checkInput() {
  $('.switchInput').each(function () {
    let e = $(this);
    if ('notificationInput' == e.attr('id')) {
      let t = $(this).data('endpoint');
      $.ajax({
        type: 'GET',
        url: `?action=check_notifications&endpoint=${t}`,
        success: function (t) {
          t.status && e.find('input[type="checkbox"]').prop('checked', !0);
        },
      });
    } else
      'emailNewsletter' == e.attr('id') &&
        $.ajax({
          type: 'GET',
          url: '?action=check_newsletter_subscription',
          success: function (t) {
            t.status && e.find('input[type="checkbox"]').prop('checked', !0);
          },
        });
  });
}
export function subscribeNewsletter() {
  let e = $('[name="csrftoken"]')[0].content;
  $.ajax({
    type: 'POST',
    headers: { 'X-CSRFToken': e },
    url: '?action=subscribe_newsletter',
    success: function (e) {
      e.status
        ? showSuccessMessage(
            'NewsLetter Subscription',
            'You have subscribed to Smst Newsletter.'
          )
        : showErrorMessage('Error Occurred', 'Kindly Try Again');
    },
  });
}
export function saveImage() {
  ($('#imageEditPreview')
    .cropper('getCroppedCanvas')
    .toBlob(
      function (e) {
        const t = URL.createObjectURL(e);
        $('#imgPreview')[0].src = t;
        const a = new File([e], 'product_image.jpg', {
            type: 'image/jpeg',
            lastModified: Date.now(),
          }),
          o = new DataTransfer();
        (o.items.add(a), ($('#imageInput')[0].files = o.files));
      },
      'image/webp',
      0.9
    ),
    fadeOutModal('.imageEdit', '.imageEditHolder'),
    $('.imagePreviewHolder').addClass('animate__fadeIn'));
}
export function fadeInModal(e, t) {
  $(t)
    .removeClass('animate__fadeOut')
    .addClass('animate__fadeIn')
    .one('animationend', function () {
      ($(e).removeClass('animate__fadeOutDown').addClass('animate__fadeInUp'),
        fadeOutLoader());
    });
}
export function fadeOutModal(e, t) {
  $(e)
    .removeClass('animate__fadeInUp')
    .addClass('animate__fadeOutDown')
    .one('animationend', function () {
      $(t).removeClass('animate__fadeIn').addClass('animate__fadeOut');
    });
}
export function loaderScreen(e) {
  let t = $(
      '<div class="smst_loader animate__animated animate__fadeIn"></div>'
    ),
    a = $('<div class="smst_loader_holder"></div>'),
    o = $('<div class="badge_logo"></div>'),
    n = $(`<div class="loader_message"><span>${e}</span></div>`);
  (t.append(a.append(o, n)), $('body').append(t));
}
export function fadeOutLoader() {
  $('.smst_loader')
    .removeClass('animate__fadeIn')
    .addClass('animate__fadeOut')
    .one('animationend', function () {
      $(this).remove();
    });
}
